/**
 * Closing is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. It is final: the org stops
 * resolving for everyone, and its subscription ends at the moment of closing.
 * Closing an already-closed org is a conflict, as archiving an archived
 * project is.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  assertNotArchived("Organization", org.id, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const now = new Date();
  const closed = await orgRepo.archiveOrg(input.orgId, now);
  // Null means a concurrent close won the race between the read and the write.
  if (closed === null) {
    throw new AlreadyArchivedError("Organization", input.orgId);
  }

  await subscriptionRepo.endSubscription(input.orgId, toIsoTimestamp(now));

  return closed;
}

/** True once the workspace has been closed; background work and actions skip it. */
export async function isOrganizationClosed(orgId: OrgId): Promise<boolean> {
  const org = await orgRepo.findOrgById(orgId);
  return org !== null && isArchived(org);
}

